    setIsTyping(true);
    const lowerInput = userInput.toLowerCase();
    let responseText: React.ReactNode = "";
    let nextContext: ChatContext = 'idle';

    setTimeout(() => {
      // --- Context: Order Tracking ---
      if (chatContext === 'tracking_order') {
        // Mock tracking logic
        if (userInput.length > 3) {
            // Check if it matches a mock order or just give a generic success
            const foundOrder = orders.find(o => o.id.toLowerCase() === lowerInput || o.id.toLowerCase().includes(lowerInput));

            if (foundOrder) {
                 responseText = `📦 Order ${foundOrder.id} is currently **${foundOrder.status}**. It was placed on ${foundOrder.date}.`;
            } else if (lowerInput.startsWith('ord')) {
                 responseText = `📦 Your order ${userInput.toUpperCase()} is currently out for delivery. Expect it by 6 PM today.`;
