                 responseText = "I couldn't find that specific Order ID. Please try again or check your 'Orders' page.";
            }
        } else {
            responseText = "That doesn't look like a valid Order ID. Please enter something like 'ORD-2024-001'.";
        }
      } 

      // --- Flow 1 & 2: Search & Recommendations ---
      else if (lowerInput.includes('show') || lowerInput.includes('search') || lowerInput.includes('suggest') || lowerInput.includes('recommend') || lowerInput.includes('find') || lowerInput.includes('buy')) {

        let foundProducts = [];
        let category = "";

        if (lowerInput.includes('watch')) { category = 'Smart Wearables'; }
        else if (lowerInput.includes('phone') || lowerInput.includes('mobile')) { category = 'Mobiles & Tablets'; }
        else if (lowerInput.includes('audio') || lowerInput.includes('earbud') || lowerInput.includes('speaker') || lowerInput.includes('headphone')) { category = 'Audio'; }
        else if (lowerInput.includes('home') || lowerInput.includes('camera') || lowerInput.includes('plug')) { category = 'Smart Home'; }
